        "   悬空线头（不知道下一步往哪走）、& 印记（碰到了但撞不动）。\n"
        "   不要写「决定不碰」的（那些在第三段）。\n"
        "三、★ 我决定不碰什么，为什么——逐条写主动悬置。\n"
